CREATE TABLE sponsor_campaigns(id TEXT PRIMARY KEY,slot TEXT NOT NULL CHECK(slot IN ('hero','home-inline','detail')),category TEXT NOT NULL CHECK(category IN ('all','gpt','claude','gemini','grok','cursor')),status TEXT NOT NULL CHECK(status IN ('draft','active','paused')),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL CHECK(ends_at>starts_at),revision INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL CHECK(json_valid(data)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX sponsor_live ON sponsor_campaigns(status,slot,starts_at,ends_at);
CREATE TRIGGER sponsor_insert_conflict BEFORE INSERT ON sponsor_campaigns WHEN NEW.status='active' AND EXISTS(SELECT 1 FROM sponsor_campaigns c WHERE c.status='active' AND c.slot=NEW.slot AND c.starts_at<NEW.ends_at AND c.ends_at>NEW.starts_at AND (c.category='all' OR NEW.category='all' OR c.category=NEW.category)) BEGIN SELECT RAISE(ABORT,'sponsor_schedule_conflict'); END;
CREATE TRIGGER sponsor_update_conflict BEFORE UPDATE ON sponsor_campaigns WHEN NEW.status='active' AND EXISTS(SELECT 1 FROM sponsor_campaigns c WHERE c.id<>NEW.id AND c.status='active' AND c.slot=NEW.slot AND c.starts_at<NEW.ends_at AND c.ends_at>NEW.starts_at AND (c.category='all' OR NEW.category='all' OR c.category=NEW.category)) BEGIN SELECT RAISE(ABORT,'sponsor_schedule_conflict'); END;
CREATE TABLE sponsor_revisions(campaign_id TEXT NOT NULL REFERENCES sponsor_campaigns(id),revision INTEGER NOT NULL,data TEXT NOT NULL,at TEXT NOT NULL,PRIMARY KEY(campaign_id,revision));
CREATE TRIGGER sponsor_revision_insert AFTER INSERT ON sponsor_campaigns BEGIN INSERT INTO sponsor_revisions VALUES(NEW.id,NEW.revision,json_object('creative',json(NEW.data),'slot',NEW.slot,'category',NEW.category,'status',NEW.status,'starts_at',NEW.starts_at,'ends_at',NEW.ends_at),NEW.updated_at); END;
CREATE TRIGGER sponsor_revision_update AFTER UPDATE ON sponsor_campaigns BEGIN INSERT INTO sponsor_revisions VALUES(NEW.id,NEW.revision,json_object('creative',json(NEW.data),'slot',NEW.slot,'category',NEW.category,'status',NEW.status,'starts_at',NEW.starts_at,'ends_at',NEW.ends_at),NEW.updated_at); END;
CREATE TABLE sponsor_assets(id TEXT PRIMARY KEY,mime TEXT NOT NULL,size INTEGER NOT NULL,bytes BLOB NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE sponsor_deliveries(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES sponsor_campaigns(id),revision INTEGER NOT NULL,viewer_hash TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,impression_at TEXT,click_at TEXT);
CREATE INDEX sponsor_delivery_expiry ON sponsor_deliveries(expires_at);
CREATE TABLE sponsor_daily(campaign_id TEXT NOT NULL REFERENCES sponsor_campaigns(id),day TEXT NOT NULL,impressions INTEGER NOT NULL DEFAULT 0,clicks INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(campaign_id,day));
CREATE TRIGGER sponsor_impression AFTER UPDATE OF impression_at ON sponsor_deliveries WHEN OLD.impression_at IS NULL AND NEW.impression_at IS NOT NULL BEGIN INSERT INTO sponsor_daily(campaign_id,day,impressions) VALUES(NEW.campaign_id,date(NEW.impression_at,'+8 hours'),1) ON CONFLICT(campaign_id,day) DO UPDATE SET impressions=impressions+1; END;
CREATE TRIGGER sponsor_click AFTER UPDATE OF click_at ON sponsor_deliveries WHEN OLD.click_at IS NULL AND NEW.click_at IS NOT NULL BEGIN INSERT INTO sponsor_daily(campaign_id,day,clicks) VALUES(NEW.campaign_id,date(NEW.click_at,'+8 hours'),1) ON CONFLICT(campaign_id,day) DO UPDATE SET clicks=clicks+1; END;
CREATE TABLE sponsor_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX sponsor_limit_expiry ON sponsor_limits(expires_at);
CREATE TABLE sponsor_inquiries(id TEXT PRIMARY KEY,brand TEXT NOT NULL,contact TEXT NOT NULL,message TEXT NOT NULL,slot TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','contacted','closed')),created_at TEXT NOT NULL);
CREATE INDEX sponsor_inquiry_status ON sponsor_inquiries(status,created_at);
